def checkCollision(p, rect):
    min_x = rect[0][0]
    max_x = rect[0][0]
    min_y = rect[0][1]
    max_y = rect[0][1]

    for pt in rect:
        if pt[0] < min_x:
            min_x = pt[0]
        if pt[0] > max_x:
            max_x = pt[0]
        if pt[1] < min_y:
            min_y = pt[1]
        if pt[1] > max_y:
            max_y = pt[1]

    if p[0] >= min_x and p[0] <= max_x and p[1] >= min_y and p[1] <= max_y:
        return True
    else:
        return False

ans1 = input("Enter coordinate of cannon ball: ")
p = [float(ans1.split(",")[0]), float(ans1.split(",")[1])]

ans2 = input("Enter boundary of castle: ")
rect = []
parts = ans2.split()
for pt_str in parts:
    pt = [float(pt_str.split(",")[0]), float(pt_str.split(",")[1])]
    rect.append(pt)

if checkCollision(p, rect):
    print("hit")
else:
    print("not hit")
